// Format Twitter payload into unified schema
const body = $json.body;
const tweets = body.tweet_create_events || [];
const results = [];

for (const tweet of tweets) {
  // Skip retweets
  if (tweet.retweeted_status) continue;

  const media = (tweet.extended_entities?.media || tweet.entities?.media || [])
    .filter(m => m.type === 'photo')
    .map(m => m.media_url_https);

  results.push({
    platform: 'twitter',
    external_id: tweet.id_str,
    content: tweet.full_text || tweet.text || '',
    external_url: `https://twitter.com/i/web/status/${tweet.id_str}`,
    media_urls: media,
    likes: tweet.favorite_count || 0,
    reposts: tweet.retweet_count || 0,
    replies: tweet.reply_count || 0,
    published_at: new Date(tweet.created_at).toISOString(),
    raw_payload: tweet
  });
}

return results;

// Format LinkedIn payload into unified schema
const body = $json.body;
const events = body.events || [body];
const results = [];

for (const event of events) {
  const eventType = event.type || event['com.linkedin.eventType'] || '';
  if (!eventType.includes('SHARE') && !eventType.includes('POST') && 
      !eventType.includes('share') && !eventType.includes('post')) continue;

  const urn = event.activity || event.id || event.urn || '';
  const externalId = urn.split(':').pop() || urn;
  if (!externalId) continue;

  const shareContent = event.specificContent?.['com.linkedin.ugc.ShareContent'] || {};
  const text = shareContent.shareCommentary?.text || 
               shareContent.text || 
               event.commentary || 
               event.text?.text || '';

  if (!text) continue;

  results.push({
    platform: 'linkedin',
    external_id: externalId,
    content: text,
    external_url: `https://www.linkedin.com/feed/update/${urn}`,
    media_urls: [],
    likes: event.socialCounts?.numLikes || 0,
    reposts: event.socialCounts?.numShares || 0,
    replies: event.socialCounts?.numComments || 0,
    published_at: event.created?.time ? new Date(event.created.time).toISOString() : new Date().toISOString(),
    raw_payload: event
  });
}

return results;

// Parse OpenAI response and merge with original post data
const post = $('Is New Post?').item.json;
const aiRaw = $json.message?.content || '{}';

let ai = {};
try {
  const clean = aiRaw.replace(/```json|```/g, '').trim();
  ai = JSON.parse(clean);
} catch(e) {
  ai = { summary: post.content.slice(0, 200), tags: [], category: 'General', seo_desc: post.content.slice(0, 155) };
}

// Calculate reading time
const words = post.content.trim().split(/\s+/).length;
const reading_time = Math.max(1, Math.ceil(words / 200));

return [{
  ...post,
  ai_summary: ai.summary || post.content.slice(0, 200),
  ai_tags: Array.isArray(ai.tags) ? ai.tags : [],
  ai_category: ai.category || 'General',
  ai_seo_desc: ai.seo_desc || post.content.slice(0, 155),
  reading_time,
  hidden: false
}];
